            const label = (p: readonly ('f' | 'm')[]): string => p.length === 1 ? own(p[0])
                : p.length === 2 ? `${own(p[0])}’s ${own(p[1])}` : `${own(p[p.length - 1])} · ${label(p.slice(0, -1))}`;
